// Turn the classifier's JSON text into clean fields and merge with the ticket.
const ticket = $('Prepare Ticket').first().json;

let c = {};
try {
  c = JSON.parse($input.first().json.text);
} catch (error) {
  c = {};   // if the AI returned bad JSON, fall back to safe defaults
}

const allowed = ['refund', 'delivery', 'cancellation', 'product', 'other'];
const category = allowed.includes(c.category) ? c.category : 'other';
const orderFromText = String(c.order_id || '').trim().toUpperCase();

return [{
  json: {
    ...ticket,
    order_id: ticket.order_id || orderFromText,   // form field wins, else from message
    category: category,
    about_specific_order: c.about_specific_order === true,
    wants_human: c.wants_human === true,
    legal_threat: c.legal_threat === true,
    safety_issue: c.safety_issue === true,
    summary: c.summary || ''
  }
}];

// RULES ENGINE: company rules decide WHAT to do. The AI only writes the words.
const t = $('Parse Classification').first().json;
const rows = $input.all().map(item => item.json).filter(row => row.order_id);
const order = rows.length > 0 ? rows[0] : null;

// ---- date helpers (the ticket date is "today", support_rules section 7) ----
function toDate(value) {
  return new Date(String(value).slice(0, 10) + 'T00:00:00Z');
}
const today = toDate(t.created_at);
function daysSince(value) {
  return Math.round((today - toDate(value)) / 86400000);
}
function businessDaysSince(value) {
  const d = toDate(value);
  let count = 0;
  while (d < today) {
    d.setUTCDate(d.getUTCDate() + 1);
    const day = d.getUTCDay();
    if (day !== 0 && day !== 6) count = count + 1;
  }
  return count;
}
function dateText(value) {
  return value ? String(value).slice(0, 10) : '';
}

const AUTO_REFUND_LIMIT = 2000;   // Rs, from refund policy section 4
let action = 'answer';
let reason = '';
let points = [];
let refundAmount = 0;
const orderTopics = ['refund', 'delivery', 'cancellation'];
const needsOrder = orderTopics.includes(t.category) && t.about_specific_order;

// ---- 1. Escalations come first ----
if (t.safety_issue) {
  action = 'escalate';
  reason = 'Safety issue reported';
  points.push('Tell the customer to stop using the product immediately.');
  points.push('Say a human support lead will contact them soon.');
} else if (t.legal_threat || t.wants_human) {
  action = 'escalate';
  reason = t.legal_threat ? 'Legal threat' : 'Customer asked for a human';
  points.push('Say the ticket has been escalated and a human support lead will contact them soon.');

// ---- 2. Missing or wrong order ID ----
} else if (t.order_id && !order) {
  action = 'ask_info';
  reason = 'Order ID not found';
  points.push('Say we could not find order ' + t.order_id + ' and ask for the correct order ID.');
} else if (!t.order_id && needsOrder) {
  action = 'ask_info';
  reason = 'Order ID missing';
  points.push('Ask the customer for their order ID.');

// ---- 3. Identity check: email must match the order ----
} else if (order && String(order.customer_email).toLowerCase() !== t.customer_email) {
  action = 'verify_identity';
  reason = 'Email does not match the order';
  points.push('Do not share any order details.');
  points.push('Ask the customer to write from their registered email address (the one used for the order).');

// ---- 4. Delivery questions about an order ----
} else if (order && t.category === 'delivery') {
  if (order.status === 'shipped' && businessDaysSince(order.est_delivery_date) > 3) {
    action = 'escalate';
    reason = 'Shipped order more than 3 business days late';
    points.push('Apologise for the delay. Say the ticket has been escalated to our logistics team. Do not promise a new date.');
  } else if (order.status === 'shipped') {
    reason = 'Order is on the way';
    points.push('Say the order is shipped and the estimated delivery date is ' + dateText(order.est_delivery_date) + '.');
  } else if (order.status === 'delivered') {
    reason = 'Order already delivered';
    points.push('Say the order was delivered on ' + dateText(order.delivered_date) + '.');
  } else if (order.status === 'processing') {
    reason = 'Order not shipped yet';
    points.push('Say the order is being processed and has not shipped yet.');
  } else {
    reason = 'Order is cancelled';
    points.push('Say the order is cancelled.');
  }

// ---- 5. Refund requests ----
} else if (order && t.category === 'refund') {
  if (order.refund_status === 'refunded') {
    action = 'deny';
    reason = 'Order already refunded';
    points.push('Say this order was already refunded, so it cannot be refunded again.');
  } else if (order.category === 'digital') {
    action = 'deny';
    reason = 'Gift cards and digital products are non-refundable';
    points.push('Explain that gift cards cannot be refunded.');
  } else if (order.status === 'processing') {
    reason = 'Order not shipped yet';
    points.push('Say the order has not shipped yet, so they can cancel it free of charge for a full refund.');
  } else if (order.status === 'shipped') {
    reason = 'Order not delivered yet';
    points.push('Say the order is on the way. After delivery they can request a return within 7 days.');
  } else if (order.status === 'cancelled') {
    reason = 'Order already cancelled';
    points.push('Say the order is already cancelled.');
  } else {
    const days = daysSince(order.delivered_date);
    if (days > 7) {
      action = 'deny';
      reason = 'Return window of 7 days is over (' + days + ' days since delivery)';
      points.push('Explain the 7-day return window has ended. Offer a repair or replacement under the warranty.');
    } else {
      refundAmount = Number(order.amount);
      const payNote = order.payment_method === 'COD'
        ? 'Because it was a cash on delivery order, the refund goes as ShaikMart store credit or to a UPI ID they share.'
        : 'The refund goes to the original payment method in 5-7 business days after approval.';
      if (refundAmount <= AUTO_REFUND_LIMIT) {
        action = 'refund_auto';
        reason = 'Within 7 days and Rs ' + refundAmount + ' is within the auto-approval limit';
        points.push('Confirm a full refund of Rs ' + refundAmount + ' is approved. ' + payNote + ' A pickup will be arranged.');
      } else {
        action = 'refund_approval';
        reason = 'Within 7 days but Rs ' + refundAmount + ' is above the Rs 2,000 auto-approval limit';
        points.push('Say the refund request of Rs ' + refundAmount + ' is under review by a support lead. Do NOT say it is approved.');
      }
    }
  }

// ---- 6. Cancellation requests ----
} else if (order && t.category === 'cancellation') {
  if (order.status === 'processing') {
    action = 'cancel';
    reason = 'Order not shipped yet, free cancellation';
    refundAmount = order.payment_method === 'COD' ? 0 : Number(order.amount);
    if (order.payment_method === 'COD') {
      points.push('Confirm the order is cancelled. It was cash on delivery, so no payment was taken.');
    } else {
      points.push('Confirm the order is cancelled and Rs ' + refundAmount + ' will be refunded to the original payment method in 5-7 business days.');
    }
  } else if (order.status === 'cancelled') {
    reason = 'Order already cancelled';
    points.push('Say the order is already cancelled.');
  } else if (order.status === 'shipped') {
    action = 'deny';
    reason = 'Shipped orders cannot be cancelled';
    points.push('Explain shipped orders cannot be cancelled, but they can refuse the parcel at delivery.');
  } else {
    action = 'deny';
    reason = 'Delivered orders cannot be cancelled';
    points.push('Explain delivered orders cannot be cancelled, but they can request a return within 7 days of delivery.');
  }

// ---- 7. Everything else: answer from the policies ----
} else {
  reason = 'General question';
  points.push('Answer the question using the policy_search tool. If the policies do not cover it, say a support executive will follow up.');
}

// Facts the AI may use. Never share order details if identity failed.
const orderFacts = (order && action !== 'verify_identity') ? {
  order_id: order.order_id,
  product: order.product,
  amount_rs: Number(order.amount),
  payment_method: order.payment_method,
  order_date: dateText(order.order_date),
  status: order.status,
  est_delivery_date: dateText(order.est_delivery_date),
  delivered_date: dateText(order.delivered_date),
  refund_status: order.refund_status,
  customer_name: order.customer_name
} : 'not shared';

const facts = { today: t.created_at, category: t.category, order: orderFacts };
const block =
  'CUSTOMER MESSAGE:\n' + t.message +
  '\n\nDECISION (made by company rules - do not change it): ' + action +
  '\nREASON: ' + reason +
  '\n\nFACTS:\n' + JSON.stringify(facts, null, 2) +
  '\n\nREQUIRED POINTS:\n- ' + points.join('\n- ');

return [{
  json: {
    ...t,
    order_found: order !== null,
    action: action,
    reason: reason,
    refund_amount: refundAmount,
    points: points,
    agent_input: block + '\n\nWrite the reply to the customer now.',
    verify_input: block
  }
}];

// Use the AI reply only if the verifier approved it; otherwise send a safe template.
const d = $('Decide Action').first().json;
const draft = String($('Write Reply').first().json.output || '').trim();

let v = {};
try {
  v = JSON.parse($input.first().json.text);
} catch (error) {
  v = { ok: false, problems: ['Verifier output could not be read'] };
}

const fallback = {
  answer: 'Thank you for contacting ShaikMart. A support executive will review your question and reply shortly. - ShaikMart Support',
  refund_auto: 'Your refund request has been accepted. You will receive a confirmation with the pickup details shortly. - ShaikMart Support',
  refund_approval: 'Your refund request is under review by our support lead. We will update you soon. - ShaikMart Support',
  deny: 'Sorry, we are unable to process this request under our policy. A support executive will share more details shortly. - ShaikMart Support',
  cancel: 'Your order has been cancelled. You will receive a confirmation shortly. - ShaikMart Support',
  escalate: 'Your ticket has been escalated and a human support lead will contact you soon. - ShaikMart Support',
  verify_identity: 'For your security, please write to us from the email address registered on the order. - ShaikMart Support',
  ask_info: 'Please share your order ID so we can help you. - ShaikMart Support'
};

const ok = v.ok === true && draft.length > 0;

return [{
  json: {
    ...d,
    reply: ok ? draft : fallback[d.action],
    verifier_ok: ok,
    verifier_problems: v.problems || [],
    needs_human: d.action === 'refund_approval' || d.action === 'escalate'
  }
}];

