// Build one audit row. If a human was asked on Telegram, record their decision.
const f = $('Finalize Reply').first().json;
const input = $input.first().json;

let humanDecision = 'not_needed';
if (f.needs_human) {
  const approved = input.data && input.data.approved === true;
  humanDecision = approved ? 'approved' : 'rejected';
}

return [{ json: { ...f, human_decision: humanDecision } }];
